/* AM: Multiverso · Wiki del Coliseo. Aplicación estática, sin dependencias. */
(function(){'use strict';
 const D=window.COLISEO_DATA,C=window.WikiCore,main=document.getElementById('contenido');
 const byId=Object.fromEntries(D.characters.map(c=>[c.id,c])),moves=Object.fromEntries(D.moves.map(m=>[m.id,m])),anomalies=Object.fromEntries(D.anomalies.map(a=>[a.character,a]));
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const inline=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
 const glyphs={Fuego:'♨',Agua:'◒',Hielo:'❄',Rayo:'ϟ',Naturaleza:'❧',Tierra:'▲',Tecnológico:'▣',Veneno:'♧',Viento:'≋',Marcial:'✦',Arcano:'✧',Luz:'☼',Oscuridad:'☾',Espiritual:'⁙',Sonoro:'♬'};
 const iconPaths={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',characters:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',moves:'<path d="m4 3 13 13m-3 3 5-5M3 4l3 6 4-4Zm17-1L7 16m-3-2 6 6"/>',passives:'<path d="m12 3 2.5 5.8L21 10l-4.8 4.3 1.3 6.4L12 17.4l-5.5 3.3 1.3-6.4L3 10l6.5-1.2Z"/>',objects:'<path d="M4 9h16v12H4zM3 5h18v4H3zM12 5v16"/><path d="M12 5c-5 0-6-1-5-3 2-2 5 3 5 3Zm0 0c5 0 6-1 5-3-2-2-5 3-5 3Z"/>',elements:'<path d="m12 3 8 5v9l-8 5-8-5V8zM4 8l8 5 8-5m-8 5v9"/>',environments:'<path d="M6 17a5 5 0 1 1 1-9 6 6 0 0 1 11 3 3 3 0 1 1 0 6ZM8 21h.01M13 21h.01M18 21h.01"/>',anomalies:'<circle cx="12" cy="12" r="8"/><path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',guides:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3ZM12 6v16M6 9h3m-3 4h3m6-4h3m-3 4h3"/>',news:'<path d="M5 4h14v17H5ZM8 8h8m-8 4h8m-8 4h5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',compare:'<path d="M4 4h5v16H4Zm11 4h5v12h-5ZM2 22h20"/>',star:'<path d="m12 3 2.5 5.8L21 10l-4.8 4.3 1.3 6.4L12 17.4l-5.5 3.3 1.3-6.4L3 10l6.5-1.2Z"/>'};
 const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[k]||iconPaths.elements}</svg>`;
 const roles=['Asesino','Mago','Tanque','Melee','Apoyo','Control','Anomalía'];
 const fnum=n=>C.factorText(n),elPill=(e,extra='')=>`<span class="pill" style="--element:${D.colors[e]}"><i aria-hidden="true">${glyphs[e]||'◇'}</i>${esc(e)}${extra}</span>`;
 const initials=c=>c.name.split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();
 const art=(c,cls='',eager=false)=>D.images[c.id]?`<img class="${cls}" src="${D.images[c.id]}" alt="${esc(c.name)}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`:`<div class="monogram" aria-hidden="true"><span>${initials(c)}</span></div>`;
 const avatar=c=>`<span class="mini-avatar" style="--element:${D.colors[c.elements[0]]}">${D.images[c.id]?`<img src="${D.images[c.id]}" alt="" loading="lazy" decoding="async">`:initials(c)}</span>`;
 let favorites=[];try{favorites=JSON.parse(localStorage.getItem('am-coliseo-wiki:favorites')||'[]');if(!Array.isArray(favorites))favorites=[];}catch{favorites=[];}
 const favoriteButton=c=>`<button class="favorite ${favorites.includes(c.id)?'selected':''}" data-action="favorite" data-id="${c.id}" aria-label="${favorites.includes(c.id)?'Quitar de':'Agregar a'} favoritos: ${esc(c.name)}" aria-pressed="${favorites.includes(c.id)}" title="Guardar personaje">${favorites.includes(c.id)?'★':'☆'}</button>`;
 const card=c=>`<article class="character-card" style="--element:${D.colors[c.elements[0]]}">${favoriteButton(c)}<a class="card-art" href="#personaje/${c.id}" aria-label="Ver ficha de ${esc(c.name)}"><span class="role-float">${esc(c.role)}</span>${art(c)}</a><div class="card-body"><h3><a href="#personaje/${c.id}">${esc(c.name)}</a></h3><div class="chips">${c.elements.map(e=>elPill(e)).join('')}</div><div class="card-stat-line"><span>VIDA<b>${c.stats.max_life}</b></span><span>${c.stats.physical_attack>=c.stats.magic_attack?'ATQ F':'ATQ M'}<b>${Math.max(c.stats.physical_attack,c.stats.magic_attack)}</b></span><span>VEL<b>${c.stats.speed}</b></span></div></div></article>`;
 const miniTeam=id=>{const c=byId[id];return`<a href="#personaje/${c.id}" class="team-member">${avatar(c)}<span>${esc(c.name)}<small>${esc(c.role)} · ${c.elements.join(' / ')}</small></span></a>`;};
 const heading=(label,title,desc,count='')=>`<div class="page-heading"><div><div class="eyebrow">${esc(label)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${count?`<span class="subtle-count">${count}</span>`:''}</div>`;
 const section=(title,link='',label='')=>`<div class="section-heading"><h2>${title}</h2>${link?`<a class="text-link" href="${link}">${label||'Ver todos'} →</a>`:label?`<span class="label">${label}</span>`:''}</div>`;
 const empty=(title='No encontramos coincidencias',text='Probá otro nombre, elemento o rol.')=>`<div class="empty-state">${icon('search')}<h3>${title}</h3><p>${text}</p><button class="button small" data-action="reset-filters">Limpiar filtros</button></div>`;
 const options=(values,current='',blank='Todos')=>`<option value="">${blank}</option>`+values.map(x=>{const value=typeof x==='string'?x:x.value,label=typeof x==='string'?x:x.label;return`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`;}).join('');
 const field=(id,label,html,cls='')=>`<div class="filter ${cls}"><label for="${id}">${label}</label>${html}</div>`;
 const searchField=(id,label,placeholder,value)=>field(id,label,`<input id="${id}" type="search" autocomplete="off" placeholder="${placeholder}" value="${esc(value)}">`,'search');
 const tableWrap=body=>`<div class="table-wrap">${body}</div>`;
 const motionType=m=>C.typeNames[m.type]||m.type;
 const moveTable=(list,recommended=[])=>tableWrap(`<table><thead><tr><th>Movimiento</th><th>Elemento</th><th>Tipo</th><th>Poder</th><th>Precisión</th><th>Descanso</th></tr></thead><tbody>${list.map(m=>`<tr><td class="move-name"><a href="#movimiento/${m.id}">${recommended.includes(m.id)?'<i class="recommended-dot" title="Recomendado" aria-label="Recomendado"></i>':''}${esc(m.name)}</a>${D.characters.some(c=>c.signature===m.id)?'<small class="gold">Característico</small>':''}</td><td>${elPill(m.element)}</td><td class="muted">${motionType(m)}</td><td class="number">${m.power||'—'}</td><td class="number">${Math.round((m.accuracy??1)*100)}%</td><td class="number">${m.rest}</td></tr>`).join('')}</tbody></table>`);
 const maxStats=Object.fromEntries(Object.keys(C.statNames).map(k=>[k,Math.max(...D.characters.map(c=>c.stats[k]))]));
 const stats=c=>`<div class="stat-list">${Object.entries(C.statNames).map(([k,label])=>`<div class="stat-row"><span>${label}</span><div class="bar"><span style="width:${100*c.stats[k]/maxStats[k]}%"></span></div><strong>${c.stats[k]}</strong></div>`).join('')}</div>`;
 const envColor=e=>D.colors[e.element];
 let state={page:'inicio',params:new URLSearchParams(),limit:24};
 const navItems=[['inicio','Inicio','home',''],['personajes','Personajes','characters',D.characters.length],['movimientos','Movimientos','moves',D.moves.length],['pasivas','Pasivas','passives',D.characters.reduce((n,c)=>n+c.passives.length,0)],['objetos','Objetos','objects',D.equipment.length],['elementos','Elementos','elements',D.elements.length],['ambientes','Ambientes','environments',D.environments.length],['anomalias','Anomalías','anomalies',D.anomalies.length],['guias','Guías y estrategia','guides',''],['novedades','Novedades','news','']];
 function navigation(){let active=state.page;if(active==='personaje'||active==='comparar')active='personajes';if(active==='movimiento')active='movimientos';if(active==='objeto')active='objetos';if(active==='reglas')active='guias';document.getElementById('navigation').innerHTML=navItems.map(([id,label,k,count],i)=>(i===0?'<div class="nav-label">EXPLORAR</div>':i===5?'<div class="nav-label">EL CAMPO DE BATALLA</div>':i===8?'<div class="nav-label">APRENDER Y DESCUBRIR</div>':'')+`<a class="nav-link ${id===active?'active':''}" href="#${id}" ${id===active?'aria-current="page"':''}>${icon(k)}<span>${label}</span>${count?`<span class="nav-count">${count}</span>`:''}</a>`).join('');}
 function renderHome(){
 const featured=['inciner_fragmentos','inciner_blond','punchfying','xylassin'];
 return`<section class="hero"><div class="starfield"></div><span class="hero-stamp">EL ARCHIVO DEL MULTIVERSO</span><div class="hero-copy"><div class="eyebrow"><span class="pill-dot"></span>AM: MULTIVERSO · WIKI DEL COLISEO</div><h1>Conocé tu<br>próximo <span>equipo.</span></h1><p>Personajes, afinidades y nuevas formas de combatir. Toda la estrategia del Coliseo, en un solo lugar.</p><div class="button-row"><a class="button primary" href="#personajes">Explorar personajes <span>↗</span></a><a class="button quiet" href="#guias">Cómo se juega →</a></div></div><div class="hero-art" aria-hidden="true">${art(byId.inciner_fragmentos,'hero-back',true)}${art(byId.inciner_blond,'hero-front',true)}</div></section>
 <div class="stat-strip">${[[D.characters.length,'Personajes','characters'],[D.moves.length,'Movimientos','moves'],[D.elements.length,'Elementos','elements'],[D.environments.length,'Ambientes','environments']].map(([n,label,k])=>`<div class="stat-box">${icon(k)}<div><b>${n}</b><span>${label}</span></div></div>`).join('')}</div>
 ${section('Nuevas caras del Coliseo','#personajes','Explorar el plantel')}<div class="roster-grid home-roster">${featured.map(id=>card(byId[id])).join('')}</div>
 ${section('El campo cambia. Tu estrategia también.')}<div class="home-grid"><a class="callout-card purple" href="#ambientes?campo=anomalous"><span class="glyph">${icon('environments')}</span><h3>Un campo fuera de lo normal.</h3><p>Campo Anómalo reduce las curaciones un 85% y lleva la esquiva preparada al 50%. Descubrí sus efectos y cómo responder.</p><span class="text-link">Explorar los 7 ambientes →</span></a><a class="callout-card" href="#anomalias"><span class="glyph">${icon('anomalies')}</span><h3>10 Anomalías. 10 Rupturas.</h3><p>Acumulá 5 cargas y transformá el combate durante 2 rondas.</p><span class="text-link">Conocer las Rupturas →</span><div class="anomaly-dots" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div></a></div>
 ${section('Tu siguiente ventaja')}<div class="feature-links"><a class="feature-link" href="#elementos">${icon('elements')}<span><b>Buscá la afinidad</b><small>Tabla y calculadora elemental</small></span></a><a class="feature-link" href="#comparar">${icon('compare')}<span><b>Compará personajes</b><small>Estadísticas, roles y pasivas</small></span></a><a class="feature-link" href="#reglas">${icon('guides')}<span><b>Dominá las reglas</b><small>Turnos, estados y equipos</small></span></a></div>
 ${section('El Coliseo sigue creciendo','#novedades','Leer el devlog')}<div class="panel"><div class="small-label">VERSIÓN 4.3.0 · BUILD 34</div><p style="margin:12px 0 0;font-size:13px">${D.stats.duals} personajes duales, ${D.stats.thirdPassives} con tercera opción de pasiva y ${D.stats.equipment} objetos para personalizar tu equipo. Conocé todas las incorporaciones de esta versión.</p></div>`;
 }
 function renderRoster(){const p=state.params;return heading('CATÁLOGO','Encontrá tu personaje.','Explorá los estilos del Coliseo y encontrá la combinación que se adapta a tu equipo.',`${D.characters.length} personajes`)+`<div class="filters">${searchField('roster-query','Nombre o palabra clave','Buscar personaje, pasiva o elemento…',p.get('q')||'')}${field('roster-role','Rol',`<select id="roster-role">${options(roles,p.get('rol')||'','Todos los roles')}</select>`)}${field('roster-element','Elemento',`<select id="roster-element">${options(D.elements,p.get('elemento')||'','Todos los elementos')}</select>`)}${field('roster-sort','Ordenar',`<select id="roster-sort">${options([{value:'name',label:'Nombre A–Z'},...Object.entries(C.statNames).map(([value,label])=>({value,label:`Mayor ${label}`}))],p.get('orden')||'name','Incorporación')}</select>`)}<label class="check-filter"><input id="roster-favorites" type="checkbox" ${p.get('favoritos')==='1'?'checked':''}>Mis favoritos</label></div><div class="results-bar"><span id="roster-count" aria-live="polite"></span><div><a href="#comparar" class="text-link">Comparar personajes ↗</a> <span class="separator">·</span> <button class="clear-filters" data-action="reset-filters">Limpiar filtros</button></div></div><div id="roster-results" class="roster-grid"></div><div id="roster-more" class="load-more"></div>`;}
 function syncQuery(values){const p=new URLSearchParams();for(const[k,v]of Object.entries(values))if(v)p.set(k,v);state.params=p;history.replaceState(null,'',`#${state.page}${p.size?'?'+p:''}`);}
 function updateRoster(reset=true){if(reset)state.limit=24;const q=document.getElementById('roster-query').value,role=document.getElementById('roster-role').value,element=document.getElementById('roster-element').value,order=document.getElementById('roster-sort').value,only=document.getElementById('roster-favorites').checked;syncQuery({q,rol:role,elemento:element,orden:order==='name'?'':order,favoritos:only?'1':''});let list=C.searchCharacters(D,q,role,element,only,favorites);if(order==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'es'));else if(C.statNames[order])list.sort((a,b)=>b.stats[order]-a.stats[order]||a.name.localeCompare(b.name,'es'));document.getElementById('roster-count').textContent=`${list.length} ${list.length===1?'personaje':'personajes'}${q||role||element||only?(list.length===1?' encontrado':' encontrados'):' en el plantel'}`;document.getElementById('roster-results').innerHTML=list.length?list.slice(0,state.limit).map(card).join(''):empty();document.getElementById('roster-more').innerHTML=list.length>state.limit?`<button class="button" data-action="more-roster">Mostrar más <span class="muted">(${Math.min(24,list.length-state.limit)})</span></button>`:'';}
 function affinityBlocks(c,inverted=false){const list=D.elements.map(e=>({element:e,factor:C.factor(D,e,c.elements,inverted)}));return`<div class="affinities">${[['Débil ante',x=>x.factor>1],['Resiste a',x=>x.factor<1]].map(([label,filter])=>`<div class="affinity-block"><h3>${label}</h3><div class="chips">${list.filter(filter).map(x=>elPill(x.element,` <span>${fnum(x.factor)}</span>`)).join('')||'<span class="note">Sin cruces en esta categoría.</span>'}</div></div>`).join('')}</div><p class="note">Afinidad defensiva base. Los elementos distintos del defensor se multiplican una sola vez. Pasivas, objetos y ambientes pueden modificar el resultado del ataque.</p>`;}
 function renderCharacter(id){const c=byId[id];if(!c)return render404();const a=anomalies[id];return`<a href="#personajes" class="back-link">← Todos los personajes</a><div class="detail-grid"><aside class="detail-aside" style="--element:${D.colors[c.elements[0]]}"><div class="profile-art">${art(c,'',true)}${favoriteButton(c)}</div><div class="profile-caption"><span>ESTADÍSTICAS BASE</span><span>Build 34</span></div>${stats(c)}<p class="note">Los objetos y los grados modifican estos valores durante el combate.</p></aside><div class="detail-main"><div class="page-heading"><div><div class="eyebrow">${esc(c.role)}</div><h1>${esc(c.name)}</h1><div class="chips">${c.elements.map(e=>elPill(e)).join('')}${a?'<span class="pill signature">Distorsión y Ruptura</span>':''}</div></div></div><p class="identity">${esc(c.identity)}</p><div class="profile-actions"><a class="button small" href="#comparar?a=${id}">${icon('compare')} Comparar</a><button class="button small quiet" data-action="copy-link">Copiar enlace ↗</button></div>${section('Elegí tu pasiva','','Una equipada por combate')}<div class="passive-grid">${c.passives.map(p=>`<section class="passive-card"><span class="small-label">${esc(p.kind||'Pasiva')}</span><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p></section>`).join('')}</div>${a?`<section class="anomaly-box"><div class="small-label">RUPTURA · 5 CARGAS · 2 RONDAS</div><h2>${esc(a.name)}</h2><p>${esc(a.effect)}</p><p class="charge-line"><strong>Cómo carga:</strong> ${esc(a.charges)}</p></section>`:''}${section('Afinidades defensivas')}${id==='qualidad'?'<label class="check-filter" style="margin-bottom:12px"><input type="checkbox" id="qualidad-inverted"> Espejo Elemental activo</label>':''}<div id="character-affinities">${affinityBlocks(c)}</div>${section('Su movimiento característico')}<section class="passive-card"><div class="move-title"><a class="text-link" href="#movimiento/${c.signature}"><strong>${esc(moves[c.signature].name)} ↗</strong></a>${elPill(moves[c.signature].element)}<span class="pill muted">${motionType(moves[c.signature])}</span></div><p>${esc(moves[c.signature].description)}</p></section>${section('Movimientos disponibles','','26 opciones · Equipá 4')}<p class="section-description">Los puntos dorados identifican la selección recomendada del personaje.</p>${moveTable(c.moves.map(id=>moves[id]),c.recommended)}</div></div>`;}
 function renderMoves(){const p=state.params;return heading('CATÁLOGO','Cada movimiento cuenta.','Consultá sus efectos, precisión, descanso y quiénes pueden aprenderlo.',`${D.moves.length} movimientos`)+`<div class="filters">${searchField('move-query','Nombre o efecto','Buscar movimiento o efecto…',p.get('q')||'')}${field('move-element','Elemento',`<select id="move-element">${options(D.elements,p.get('elemento')||'','Todos los elementos')}</select>`)}${field('move-type','Tipo',`<select id="move-type">${options(Object.entries(C.typeNames).map(([value,label])=>({value,label})),p.get('tipo')||'','Todos los tipos')}</select>`)}<label class="check-filter"><input id="move-signature" type="checkbox" ${p.get('caracteristico')==='1'?'checked':''}>Característicos</label></div><div class="results-bar"><span id="move-count" aria-live="polite"></span><button class="clear-filters" data-action="reset-filters">Limpiar filtros</button></div><div id="move-results"></div><div class="load-more" id="move-more"></div>`;}
 function updateMoves(reset=true){if(reset)state.limit=48;const q=document.getElementById('move-query').value,element=document.getElementById('move-element').value,type=document.getElementById('move-type').value,sig=document.getElementById('move-signature').checked;syncQuery({q,elemento:element,tipo:type,caracteristico:sig?'1':''});const list=D.moves.filter(m=>(!element||element===m.element)&&(!type||type===m.type)&&(!sig||D.characters.some(c=>c.signature===m.id))&&C.includes(`${m.name} ${m.element} ${m.description}`,q)).sort((a,b)=>a.name.localeCompare(b.name,'es'));document.getElementById('move-count').textContent=`${list.length} movimientos`;document.getElementById('move-results').innerHTML=list.length?moveTable(list.slice(0,state.limit)):empty();document.getElementById('move-more').innerHTML=list.length>state.limit?'<button class="button" data-action="more-moves">Mostrar más movimientos</button>':'';}
 function renderMove(id){const m=moves[id];if(!m)return render404();const owners=D.characters.filter(c=>c.signature===id),learners=D.characters.filter(c=>c.moves.includes(id));return`<a href="#movimientos" class="back-link">← Todos los movimientos</a>${heading('MOVIMIENTO',m.name,'')}<div class="chips">${elPill(m.element)}<span class="pill muted">${motionType(m)}</span>${owners.length?'<span class="pill signature">Característico</span>':''}</div><div class="move-metrics">${[[m.power||'—','Poder'],[Math.round((m.accuracy??1)*100)+'%','Precisión'],[m.rest,'Descanso'],[(m.priority??0)>0?'+'+m.priority:m.priority??0,'Prioridad'],[m.critical_chance?Math.round(m.critical_chance*100)+'%':'—','Crítico']].map(([n,l])=>`<div><b>${n}</b><small>${l}</small></div>`).join('')}</div><div class="description-box">${esc(m.description)}</div><div class="trait-strip"><span class="traits">Objetivo: ${C.targetNames[m.target]||'Según movimiento'}</span>${m.undodgeable?'<span class="traits">Inesquivable</span>':''}${m.defense_penetration?`<span class="traits">${Math.round(m.defense_penetration*100)}% de penetración</span>`:''}${m.life_steal_ratio?`<span class="traits">${Math.round(m.life_steal_ratio*100)}% de drenaje</span>`:''}</div><p class="note">Descanso 0: disponible en la siguiente ronda. Descanso 1: deja pasar una ronda antes de volver a usarlo. La precisión y la esquiva se comprueban por separado.</p>${owners.length?`<div class="info-note">Movimiento característico de ${owners.map(c=>`<a href="#personaje/${c.id}"><strong>${esc(c.name)}</strong></a>`).join(', ')}.</div>`:''}${section('Quiénes lo aprenden','',`${learners.length} personajes`)}${learners.length?`<div class="roster-grid mini-grid">${learners.map(card).join('')}</div>`:'<div class="info-note">Este movimiento se conserva en el catálogo, pero no figura entre las 26 opciones actuales de ningún personaje.</div>'}`;}
 function renderPassives(){return heading('CATÁLOGO','Un estilo. Una pasiva.','Las pasivas acompañan a cada personaje. Se elige una antes del combate y sus límites dependen de su descripción.',`${D.characters.reduce((n,c)=>n+c.passives.length,0)} opciones`)+`<div class="filters">${searchField('passive-query','Nombre, personaje o efecto','Buscar pasiva…',state.params.get('q')||'')}${field('passive-role','Rol del personaje',`<select id="passive-role">${options(roles,state.params.get('rol')||'','Todos los roles')}</select>`)}</div><div class="results-bar"><span id="passive-count" aria-live="polite"></span><button class="clear-filters" data-action="reset-filters">Limpiar filtros</button></div><div class="small-grid" id="passive-results"></div><div class="load-more" id="passive-more"></div>`;}
 function updatePassives(reset=true){if(reset)state.limit=24;const q=document.getElementById('passive-query').value,role=document.getElementById('passive-role').value;syncQuery({q,rol:role});const list=D.characters.filter(c=>C.roleMatches(c,role)).flatMap(c=>c.passives.map(p=>({c,p}))).filter(({c,p})=>C.includes(`${c.name} ${p.name} ${p.description}`,q));document.getElementById('passive-count').textContent=`${list.length} pasivas`;document.getElementById('passive-results').innerHTML=list.length?list.slice(0,state.limit).map(({c,p})=>`<article class="passive-card"><div class="small-label">${esc(p.kind||'Pasiva')}</div><h3>${esc(p.name)}</h3><a class="text-link" href="#personaje/${c.id}">${esc(c.name)} ↗</a><p style="margin-top:12px">${esc(p.description)}</p></article>`).join(''):empty();document.getElementById('passive-more').innerHTML=list.length>state.limit?'<button class="button" data-action="more-passives">Mostrar más pasivas</button>':'';}
 const objectGlyphs=['◇','✊','⬡','♧','⌁','▤','ϟ','◎','⌖','♧','♜','✧'];
 const objectArt=o=>D.equipmentImages?.[o.id]?`<img src="${D.equipmentImages[o.id]}" alt="${esc(o.name)}" loading="lazy" decoding="async">`:`<span class="object-fallback" aria-hidden="true">${objectGlyphs[D.equipment.indexOf(o)]||'◇'}</span>`;
 function renderObjects(){return heading('EQUIPAMIENTO','El detalle que hace la diferencia.','Cada personaje puede llevar un objeto. Dentro de un equipo, cada objeto se puede utilizar una sola vez.',`${D.equipment.length} objetos`)+`<div class="small-grid">${D.equipment.map(o=>`<article class="object-card"><a class="object-art" href="#objeto/${o.id}" aria-label="Ver ficha de ${esc(o.name)}">${objectArt(o)}</a><a href="#objeto/${o.id}"><h2>${esc(o.name)} ↗</h2></a><p>${esc(o.description)}</p></article>`).join('')}</div><div class="info-note">Los dos equipos pueden utilizar el mismo objeto. La restricción de repetición se aplica dentro de cada equipo.</div>`;}
 function renderObject(id){const o=D.equipment.find(x=>x.id===id);if(!o)return render404();return`<a href="#objetos" class="back-link">← Todos los objetos</a><div class="object-detail-intro"><div class="object-detail-art">${objectArt(o)}</div>${heading('EQUIPAMIENTO',o.name,o.description)}</div><div class="panel"><h2>Cómo se combina</h2><p>Se equipa antes del combate y ocupa el único espacio de objeto del personaje. No podés repetirlo en otro integrante de tu equipo.</p>${Object.keys(o.modifiers).length?`<div class="chips">${Object.entries(o.modifiers).map(([k,v])=>`<span class="pill signature">${v>0?'+':''}${Math.round(v*100)}% ${C.statNames[k]}</span>`).join('')}</div>`:''}<p class="note">La descripción del objeto determina qué activa su efecto, cuánto dura y con qué otros efectos se combina.</p></div>${section('Explorá posibles portadores','#personajes','Ver el plantel')}<div class="roster-grid home-roster">${['inciner_fragmentos','inciner_blond','punchfying','xylassin'].map(id=>card(byId[id])).join('')}</div>`;}
 function renderElements(){return heading('AFINIDADES','Leé el cruce. Elegí tu respuesta.','Cruzá el elemento de un ataque con los del defensor. Cada movimiento tiene un elemento, aunque el personaje tenga dos.',`${D.elements.length} elementos`)+`<section class="panel calculator"><div><h2 style="font-size:18px;margin-bottom:17px">Calculadora de afinidad</h2><div class="calculator-form">${field('calc-attack','Elemento del ataque',`<select id="calc-attack">${D.elements.map(e=>`<option ${e==='Fuego'?'selected':''}>${e}</option>`).join('')}</select>`)}${field('calc-defender','Defensor: primer elemento',`<select id="calc-defender">${D.elements.map(e=>`<option ${e==='Naturaleza'?'selected':''}>${e}</option>`).join('')}</select>`)}${field('calc-second','Defensor: segundo elemento',`<select id="calc-second">${options(D.elements,'','Sin segundo elemento')}</select>`)}</div></div><div class="calc-result" id="calc-result" aria-live="polite"></div></section><div class="info-note">El resultado indica solo el multiplicador elemental del daño directo. Las estadísticas, los objetos, las pasivas y el ambiente se aplican con sus propias reglas.</div>${section('Tabla de elementos')}<p class="section-description">Filas: elemento del ataque. Columnas: elemento del defensor. Deslizá la tabla para consultar todos los cruces.</p><div class="matrix-legend"><span><i style="background:var(--green)"></i>Ventaja ×1,15</span><span><i style="background:var(--red)"></i>Resistido ×0,85</span><span><i style="background:var(--faint)"></i>Neutro ×1</span></div>${tableWrap(`<table class="matrix"><thead><tr><th>Ataque ↓<br>Defensor →</th>${D.elements.map(e=>`<th style="color:${D.colors[e]}">${e}</th>`).join('')}</tr></thead><tbody>${D.elements.map(a=>`<tr><td style="color:${D.colors[a]}">${glyphs[a]} ${a}</td>${D.elements.map(d=>{const n=C.factor(D,a,[d]);return`<td class="${n>1?'adv':n<1?'res':'neutral'}" title="${a} contra ${d}: ${fnum(n)}">${n===1?'—':fnum(n)}</td>`;}).join('')}</tr>`).join('')}</tbody></table>`)}${section('Dos elementos, un resultado')}<div class="small-grid"><div class="passive-card"><h3>Doble ventaja</h3><p>1,15 × 1,15 = <strong>×1,3225</strong>. El ataque aprovecha ambas afinidades.</p></div><div class="passive-card"><h3>Doble resistencia</h3><p>0,85 × 0,85 = <strong>×0,7225</strong>. Ambos elementos resisten ese ataque.</p></div><div class="passive-card"><h3>Cruce mixto</h3><p>1,15 × 0,85 = <strong>×0,9775</strong>. Una afinidad favorece al ataque y la otra lo resiste.</p></div></div><p class="note">La tabla actual utiliza cruces de ×1,15, ×0,85 y ×1. Algunas pasivas conceden inmunidades propias. Durante Espejo Elemental, Qualidad invierte sus factores defensivos; podés consultarlo en su ficha.</p>`;}
 function updateCalculator(){const attack=document.getElementById('calc-attack').value,a=document.getElementById('calc-defender').value,b=document.getElementById('calc-second').value,n=C.factor(D,attack,[a,b]);document.getElementById('calc-result').innerHTML=`<b class="${n>1?'factor-positive':n<1?'factor-negative':'factor-neutral'}">${fnum(n)}</b><small>${n>1?'Ventaja elemental':n<1?(n>.95?'Cruce mixto':'Ataque resistido'):'Cruce neutro'}</small><small>${[...new Set([a,b].filter(Boolean))].join(' / ')}</small>`;}
 function renderEnvironments(){const selected=state.params.get('campo'),list=[...D.environments].sort((a,b)=>(b.id===selected)-(a.id===selected));return heading('EL ESCENARIO TAMBIÉN JUEGA','Un ambiente. Dos equipos.','Cada ambiente dura 4 rondas, incluida la de invocación. Otro ambiente lo reemplaza y Disipación Ambiental puede retirarlo.',`${D.environments.length} ambientes`)+`<div class="small-grid">${list.map(e=>{const learners=D.characters.filter(c=>c.moves.some(id=>e.moves.includes(id)));return`<article class="object-card environment-card" id="campo-${e.id}" style="--element:${envColor(e)}"><div class="environment-icon" aria-hidden="true">${glyphs[e.element]}</div><div class="small-label">4 RONDAS · AMBOS EQUIPOS</div><h2 style="margin-top:10px">${e.id==='anomalous'?'Campo Anómalo':e.name}</h2><p class="environment-effect">${esc(e.description)}</p><div class="source-list"><strong>LO INVOCAN COMO MOVIMIENTO</strong>${learners.map(c=>`<a href="#personaje/${c.id}">${esc(c.name)}</a>`).join(' · ')}${e.passives.length?`<strong style="margin-top:12px">PASIVAS DE ENTRADA</strong>${e.passives.map(p=>`<a href="#personaje/${p.character}">${esc(byId[p.character].name)}</a> — ${esc(p.name)}`).join('<br>')}`:''}</div></article>`;}).join('')}</div><div class="info-note">Si una pasiva de entrada encuentra el mismo ambiente ya activo, no renueva su duración. Los cambios de VEL no reordenan acciones ya confirmadas.</div>${section('Cómo responder')}<div class="small-grid"><div class="passive-card"><h3><a href="#movimiento/A62">Aura Zero ↗</a></h3><p>Durante 3 rondas, el usuario ignora efectos ambientales. Frente a Campo Anómalo conserva su curación recibida y su probabilidad de esquiva; no protege a otro aliado solo por curarlo.</p></div><div class="passive-card"><h3><a href="#movimiento/A63">Disipación Ambiental ↗</a></h3><p>Retira el ambiente global y sus modificadores. Conserva estados, escudos y modificaciones normales de estadísticas.</p></div><div class="passive-card"><h3><a href="#movimiento/A55">Sello Espectral ↗</a></h3><p>Bloquea los movimientos de Apoyo del objetivo durante 2 rondas, incluidas invocaciones manuales de ambientes. No impide las activaciones automáticas del rol Anomalía.</p></div></div>`;}
 function renderAnomalies(){return heading('DISTORSIÓN Y RUPTURA','Cambian las reglas del combate.','Diez personajes. Diez formas de transformar el campo. La Ruptura pertenece al rol y funciona junto con la pasiva que elijas.',`${D.anomalies.length} Anomalías`)+`<div class="stat-strip" style="margin-bottom:24px">${[['5','Cargas para preparar'],['2','Rondas de Ruptura'],['2','Cargas máximas por ronda'],['1','Carga por condición y ronda']].map(([n,l])=>`<div class="stat-box"><div><b>${n}</b><span>${l}</span></div></div>`).join('')}</div><div class="info-note">Con 5 cargas, la Ruptura se activa al inicio de la siguiente ronda en que el personaje esté activo. Consume las cargas y no acumula otras mientras dura. La reserva conserva cargas pendientes; salir durante la Ruptura la termina. Quedar KO vacía el medidor.</div><div class="small-grid">${D.anomalies.map(a=>{const c=byId[a.character];return`<article class="anomaly-box" style="margin:0"><a class="team-member" href="#personaje/${c.id}">${avatar(c)}<span>${esc(c.name)}<small>${c.elements.join(' / ')}</small></span></a><h2>${esc(a.name)}</h2><p>${esc(a.effect)}</p><p class="charge-line"><strong>Distorsión:</strong> ${esc(a.charges)}</p><a class="text-link" style="display:inline-block;margin-top:17px" href="#personaje/${c.id}">Ver movimientos y pasivas →</a></article>`;}).join('')}</div>`;}
 const topics=[
 ['rondas','Rondas y orden de acciones','Cada jugador elige una acción por personaje activo. La prioridad del movimiento se resuelve antes que la VEL. El orden queda fijado al confirmar la ronda: una bajada o subida de VEL posterior no reordena las acciones ya elegidas. Un cambio voluntario también consume la acción.'],
 ['grados','Grados de estadísticas','Los grados se limitan entre −2 y +2. Sus multiplicadores son −2: ×0,6667; −1: ×0,8; 0: ×1; +1: ×1,25; +2: ×1,5. Aplicar un aumento cuando ya se alcanzó el límite no concede un grado adicional.'],
 ['precision','Precisión y esquiva','Primero se comprueba la precisión del ataque. Un fallo consume la acción y su descanso, pero no gasta una esquiva preparada del defensor. La esquiva preparada evita un ataque directo individual y sus efectos enemigos; no evita áreas ni daño periódico. En Campo Anómalo tiene 50% de éxito y se consume al intentarla tanto si funciona como si falla. Foco Interno y los movimientos inesquivables la superan y consumen al acertar.'],
 ['estados','Veneno, Quemadura y Sangrado','El Veneno progresa por cierres de ronda: 3%, 5% y después 7% de VIDA máxima. La Quemadura base quita 2%. Pasivas específicas pueden cambiar esos valores. Veneno y Quemadura pausan su daño al estar en reserva; el Veneno pausa también su progresión. Sangrado conserva su regla en reserva: 5% el primer cierre y 3% el segundo, salvo una modificación específica. Estos daños ignoran DEF, escudos, esquiva y Guardia; Piel de Granito tiene su reducción propia.'],
 ['control','Control, Mojado y Anclado','Aturdimiento deja una comprobación de 50% de poder actuar; Parálisis, de 70%, y reduce VEL 1 grado. Congelación impide actuar hasta el cierre de la próxima ronda. Los controles pendientes también impiden cambiar y después conceden resistencia temporal según sus reglas. Mojado elimina e impide Quemadura mientras dura. Anclado bloquea el cambio. Las inmunidades y resistencias se consultan en cada pasiva o movimiento.'],
 ['curacion','Curaciones, regeneración y drenaje','Curar no supera la VIDA máxima ni revive. El drenaje usa la VIDA realmente quitada al rival: los escudos y el exceso de daño sobre un KO no aportan recuperación. La regeneración se resuelve al cierre, después del daño periódico, solo si el personaje sigue vivo. Campo Anómalo reduce todas las curaciones 85%; Aura Zero protege a quien recibe la recuperación. Báculo del Alba potencia curaciones directas de Apoyo, no drenaje ni regeneración.'],
 ['escudos','Escudos y reducciones','Los escudos no se suman: se conserva el mayor restante, hasta el 35% de la VIDA máxima del receptor. Absorben daño directo después de defensas y reducciones; daño periódico y reflejos no los consumen. Las reducciones de daño directo usan la mayor vigente, sin sumarlas. Campo Anómalo conserva el valor de los escudos. El sustituto de Liquidex absorbe antes del escudo normal.'],
 ['elementos','Elementos y tipo de ataque','Físico y Mágico determinan qué estadísticas usa el movimiento. El elemento determina su afinidad frente al defensor. Un personaje puede tener dos elementos, pero cada movimiento tiene uno. Las dos afinidades del defensor se multiplican. Los objetos y movimientos que aumentan daño por afinidad aplican sus propias condiciones; tener dos elementos no duplica esos bonos.'],
 ['apoyos','Apoyos, pasivas y Sello Espectral','Se equipan 4 movimientos y una sola pasiva por personaje. Las pasivas no ocupan espacios de movimiento ni consumen por sí mismas una acción. Sus condiciones y límites figuran en la descripción. Sello Espectral impide usar movimientos de Apoyo, incluidas curaciones y escudos, por 2 rondas; también bloquea ambientes invocados como movimiento. Las activaciones automáticas del rol Anomalía siguen sus reglas.'],
 ['descanso','Descanso y duración','Un movimiento con descanso 0 está disponible al volver a actuar. Con descanso 1, utilizado en la ronda r, vuelve en r+2. Las duraciones normales incluyen la ronda de aplicación: 2 rondas significa la actual y la siguiente. Las Rupturas se preparan con 5 cargas y comienzan al inicio de una ronda posterior, durante 2 rondas completas.'],
 ['final','KO y cierre del combate','El daño periódico se aplica antes de regenerar. Un personaje que llega a 0 queda KO y no se cura en esa fase. La victoria se comprueba al completar la resolución correspondiente, incluidas reacciones. El límite normal es de 35 rondas; al alcanzarlo se compara el promedio de porcentajes de VIDA de los equipos iniciales, con los KO en 0. Puede haber empate.'],
 ['online','Combates online y salas','Cada decisión online tiene 90 segundos. El primer plazo agotado suma un AFK y pierde la acción; el segundo concede la victoria al rival. Las salas privadas admiten dos espectadores visibles además de los jugadores y permiten rotarlos entre combates. Ambos jugadores confirman LISTO. La búsqueda de rival y sus resultados se integran en el ranking Online.']
 ];
 function renderRules(){return heading('GUÍA DE COMBATE','Las reglas, sin perderte.','Una referencia rápida para resolver las interacciones que cambian una partida.')+`<div class="chips" style="margin-bottom:25px">${topics.map(([id,name])=>`<button class="button small quiet" data-action="open-topic" data-id="${id}">${name.split(',')[0]}</button>`).join('')}</div><div class="prose">${topics.map(([id,name,text],i)=>`<details class="panel" id="regla-${id}" style="margin-bottom:12px" ${state.params.get('tema')===id||(!state.params.has('tema')&&i===0)?'open':''}><summary style="cursor:pointer;font-family:Manrope,system-ui,sans-serif;font-weight:650;font-size:15px">${name}</summary><p style="margin:14px 0 0">${text}</p></details>`).join('')}</div>`;}
 function renderGuides(){const teams=[{tag:'EJEMPLO · PRESIÓN Y RECUPERACIÓN',name:'Encontrá tu equilibrio',text:'Combiná presión física, curación y control del ritmo. Guardá un reemplazo sano y elegí la pasiva de Inciner Blond según el plan: Presencia Anómala también reduce tus propias curaciones.',ids:['inciner_blond','coldgrass','xylassin','aguatsu']},{tag:'EJEMPLO · CONTROL DE AMBIENTE',name:'Prepará el campo',text:'Campo Anómalo presiona la recuperación. Los escudos conservan su valor y un ambiente distinto puede reemplazarlo. Usá Disipación Ambiental o una invocación de lluvia cuando el campo deje de favorecerte.',ids:['inciner_fragmentos','rainycloud','golem','punchfying']}];return heading('GUÍAS Y ESTRATEGIA','Un buen equipo tiene un plan.','Ideas para empezar a combinar roles, elementos y herramientas. Estas propuestas se basan en las mecánicas de la Build 34.')+`<div class="home-grid"><a class="feature-link" href="#reglas">${icon('guides')}<span><b>Reglas de combate</b><small>Estados, turnos, precisión y escudos</small></span></a><a class="feature-link" href="#comparar">${icon('compare')}<span><b>Comparar personajes</b><small>Elegí dos fichas y cruzá sus estadísticas</small></span></a></div>${section('Antes de confirmar el equipo')}<ol class="guide-steps"><li><strong>Definí qué querés conseguir.</strong>Presión, desgaste, control o recuperación. Elegí movimientos y pasivas que acompañen ese plan.</li><li><strong>Revisá las afinidades.</strong>Dos elementos pueden combinar ventajas y resistencias. La calculadora te ayuda a encontrar qué ataques cubren los cruces difíciles.</li><li><strong>Pensá las cuatro acciones.</strong>Un repertorio con descansos variados evita depender de un único movimiento. Preparar un escudo o cambiar también tiene un coste de oportunidad.</li><li><strong>Prepará una respuesta al ambiente.</strong>Aura Zero, Disipación Ambiental y tus propias invocaciones ofrecen distintas formas de responder. Campo Anómalo también debilita el drenaje y la regeneración.</li><li><strong>Distribuí los objetos.</strong>Se equipa uno por personaje y no se repiten dentro del equipo. Precisión, penetración, defensa y curación cumplen funciones distintas.</li></ol>${section('Dos equipos para explorar')}<div class="guide-grid">${teams.map(t=>`<section class="panel guide-card"><div class="small-label">${t.tag}</div><h2>${t.name}</h2><p>${t.text}</p><div class="team-row">${t.ids.map(miniTeam).join('')}</div></section>`).join('')}</div>${section('Leer el meta de una versión')}<div class="panel prose"><p>Un personaje fuerte depende también de sus compañeros, los movimientos equipados y los rivales. Compará herramientas y condiciones: qué cura realmente, qué requiere quitar VIDA y qué puede cambiar el orden de una ronda.</p><p>Las guías son puntos de partida para probar. Las posiciones de una clasificación por victorias necesitan estadísticas reales de partidas; los ejemplos de esta wiki no representan una tabla de winrates.</p><a class="text-link" href="#novedades">Revisar las novedades de la Build 34 →</a></div>`;}
 function renderCompare(){const a=state.params.get('a'),b=state.params.get('b');const select=(id,current)=>field(id,'Personaje',`<select id="${id}">${[...D.characters].sort((a,b)=>a.name.localeCompare(b.name,'es')).map(c=>`<option value="${c.id}" ${c.id===current?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`);return heading('COMPARADOR','Dos fichas, frente a frente.','Compará estadísticas base y afinidades. Las pasivas, los objetos y los movimientos determinan cómo se aprovechan en batalla.')+`<div class="compare-selects">${select('compare-a',byId[a]?a:'inciner_fragmentos')}${select('compare-b',byId[b]?b:'inciner_blond')}</div><div class="comparison" id="comparison"></div>`;}
 function updateCompare(){const a=byId[document.getElementById('compare-a').value],b=byId[document.getElementById('compare-b').value];syncQuery({a:a.id,b:b.id});document.getElementById('comparison').innerHTML=[a,b].map((c,i)=>`<section class="panel" style="--element:${D.colors[c.elements[0]]}"><a class="profile-art comparison-portraits" href="#personaje/${c.id}">${art(c)}</a><h2 class="comparison-name" style="margin-top:20px">${esc(c.name)}</h2><p style="font-size:11px">${esc(c.role)}</p><div class="chips">${c.elements.map(e=>elPill(e)).join('')}</div><div class="stat-list">${Object.entries(C.statNames).map(([k,l])=>`<div class="stat-row"><span>${l}</span><div class="bar"><span style="width:${100*c.stats[k]/maxStats[k]}%"></span></div><strong class="${c.stats[k]>(i===0?b:a).stats[k]?'winner-stat':''}">${c.stats[k]}</strong></div>`).join('')}</div><p class="note">${c.passives.map(p=>esc(p.name)).join(' · ')}</p><a href="#personaje/${c.id}" class="text-link">Ver ficha completa →</a></section>`).join('');}
 function markdown(md){const lines=md.split('\n');let result='',i=0;while(i<lines.length){let line=lines[i];if(!line.trim()){i++;continue;}if(line.startsWith('|')&&/^\|[\s:|\-]+$/.test(lines[i+1]||'')){const rows=[];while(i<lines.length&&lines[i].startsWith('|'))rows.push(lines[i++].split('|').slice(1,-1).map(s=>s.trim()));result+=tableWrap(`<table><thead><tr>${rows[0].map(x=>`<th>${inline(x)}</th>`).join('')}</tr></thead><tbody>${rows.slice(2).map(row=>`<tr>${row.map(x=>`<td>${inline(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`);continue;}if(line.startsWith('- ')){const items=[];while(i<lines.length&&lines[i].startsWith('- '))items.push(lines[i++].slice(2));result+=`<ul>${items.map(x=>`<li>${inline(x)}</li>`).join('')}</ul>`;continue;}if(/^\*\*[^*]+\*\*$/.test(line)){result+=`<h2>${inline(line.slice(2,-2))}</h2>`;i++;continue;}const ps=[line];i++;while(i<lines.length&&lines[i].trim()&&!lines[i].startsWith('|')&&!lines[i].startsWith('- ')&&!/^\*\*[^*]+\*\*$/.test(lines[i]))ps.push(lines[i++]);result+=`<p>${inline(ps.join(' '))}</p>`;}return result;}
 function renderNews(){return heading('EL ARCHIVO','Las novedades del Multiverso.','El devlog completo de la versión actual, con sus personajes, mecánicas y mejoras.','4.3.0 · Build 34')+`<div class="button-row" style="margin-bottom:24px"><a class="button small" href="data/devlog.md" download>Descargar devlog ↗</a><a class="button small quiet" href="#personajes">Explorar el catálogo</a></div><article class="prose">${markdown(window.COLISEO_DEVLOG||'')}</article>`;}
 const render404=()=>heading('RUTA NO ENCONTRADA','Esta ficha se perdió en el Multiverso.','Podés volver al catálogo para encontrar lo que buscabas.')+'<a class="button primary" href="#personajes">Explorar personajes →</a>';
 const titles={inicio:'El archivo del Coliseo',personajes:'Personajes',personaje:'Ficha de personaje',movimientos:'Movimientos',movimiento:'Ficha de movimiento',pasivas:'Pasivas',objetos:'Objetos',objeto:'Equipamiento',elementos:'Elementos y afinidades',ambientes:'Ambientes',anomalias:'Distorsión y Ruptura',guias:'Guías y estrategia',reglas:'Reglas de combate',novedades:'Novedades',comparar:'Comparar personajes'};
 function closeMenu(){document.getElementById('sidebar').classList.remove('open');document.getElementById('drawer-scrim').classList.remove('open');document.querySelector('[data-action="toggle-menu"]').setAttribute('aria-expanded','false');}
 function route(){if(dialog.open)dialog.close();let hash=location.hash.slice(1)||'inicio';const [path,query='']=hash.split('?'),parts=path.split('/');state={page:parts[0],id:parts[1],params:new URLSearchParams(query),limit:24};const renderers={inicio:renderHome,personajes:renderRoster,personaje:()=>renderCharacter(state.id),movimientos:renderMoves,movimiento:()=>renderMove(state.id),pasivas:renderPassives,objetos:renderObjects,objeto:()=>renderObject(state.id),elementos:renderElements,ambientes:renderEnvironments,anomalias:renderAnomalies,guias:renderGuides,reglas:renderRules,comparar:renderCompare,novedades:renderNews};main.innerHTML=(renderers[state.page]||render404)();main.classList.remove('animation-enter');void main.offsetWidth;main.classList.add('animation-enter');navigation();document.getElementById('breadcrumb').innerHTML=`AM: Multiverso <span>/</span> ${esc(state.page==='personaje'&&byId[state.id]?byId[state.id].name:state.page==='movimiento'&&moves[state.id]?moves[state.id].name:titles[state.page]||'Wiki')}`;document.title=`${state.page==='personaje'&&byId[state.id]?byId[state.id].name:state.page==='movimiento'&&moves[state.id]?moves[state.id].name:titles[state.page]||'Wiki'} · Coliseo Multiversal`;if(state.page==='personajes')updateRoster();if(state.page==='movimientos')updateMoves();if(state.page==='pasivas')updatePassives();if(state.page==='elementos')updateCalculator();if(state.page==='comparar')updateCompare();closeMenu();window.scrollTo(0,0);}
 let toastTimer;function toast(text){const e=document.getElementById('toast');e.textContent=text;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2300);}
 const dialog=document.getElementById('search-dialog'),globalInput=document.getElementById('global-search');
 function searchGlobal(){const q=globalInput.value,container=document.getElementById('search-results');if(!C.normalize(q)){container.innerHTML='<div class="search-intro">Buscá un nombre, un elemento o un efecto. También podés usar Ctrl K para abrir esta ventana.</div>';return;}const groups=[['Personajes',C.searchCharacters(D,q).slice(0,5).map(c=>({name:c.name,sub:c.role+' · '+c.elements.join(' / '),url:'#personaje/'+c.id,c}))],['Movimientos',D.moves.filter(m=>C.includes(m.name+' '+m.description,q)).slice(0,5).map(m=>({name:m.name,sub:m.element+' · '+motionType(m),url:'#movimiento/'+m.id}))],['Pasivas',D.characters.flatMap(c=>c.passives.filter(p=>C.includes(p.name+' '+p.description,q)).map(p=>({name:p.name,sub:c.name,url:'#personaje/'+c.id}))).slice(0,5)],['Objetos',D.equipment.filter(o=>C.includes(o.name+' '+o.description,q)).slice(0,4).map(o=>({name:o.name,sub:'Equipamiento',url:'#objeto/'+o.id,o}))],['Ambientes',D.environments.filter(e=>C.includes((e.id==='anomalous'?'Campo Anómalo':e.name)+' '+e.description,q)).map(e=>({name:e.id==='anomalous'?'Campo Anómalo':e.name,sub:'Ambiente · 4 rondas',url:'#ambientes?campo='+e.id}))]];container.innerHTML=groups.filter(([,items])=>items.length).map(([label,items])=>`<div class="search-group-label">${label}</div>${items.map(x=>`<a class="search-result" href="${x.url}">${x.c?avatar(x.c):x.o?`<span class="mini-avatar object-mini">${objectArt(x.o)}</span>`:''}<span><b>${esc(x.name)}</b><small>${esc(x.sub)}</small></span><span class="search-arrow">↗</span></a>`).join('')}`).join('')||'<div class="search-intro">No hay coincidencias. Probá con otra palabra.</div>';}
 function openSearch(){if(!dialog.open)dialog.showModal();globalInput.value='';searchGlobal();globalInput.focus();}
 document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();main.focus();main.scrollIntoView({block:'start'});return;}const target=e.target.closest('[data-action]');if(e.target.closest('.search-result'))dialog.close();if(!target)return;const a=target.dataset.action;if(a==='open-search')openSearch();else if(a==='close-search')dialog.close();else if(a==='toggle-menu'){const open=document.getElementById('sidebar').classList.toggle('open');document.getElementById('drawer-scrim').classList.toggle('open',open);target.setAttribute('aria-expanded',String(open));}else if(a==='favorite'){const id=target.dataset.id;if(!byId[id])return;const exists=favorites.includes(id);favorites=exists?favorites.filter(x=>x!==id):[...favorites,id];try{localStorage.setItem('am-coliseo-wiki:favorites',JSON.stringify(favorites));}catch{}document.querySelectorAll(`.favorite[data-id="${id}"]`).forEach(b=>{b.classList.toggle('selected',!exists);b.innerHTML=exists?'☆':'★';b.setAttribute('aria-pressed',String(!exists));b.setAttribute('aria-label',`${exists?'Agregar a':'Quitar de'} favoritos: ${byId[id].name}`);});if(state.page==='personajes'&&document.getElementById('roster-favorites').checked)updateRoster(false);toast(exists?'Personaje quitado de favoritos':'Personaje guardado en favoritos');}else if(a==='reset-filters'){const p=state.page;location.hash=p;if(location.hash==='#'+p){state.params=new URLSearchParams();route();}}else if(a==='more-roster'){state.limit+=24;updateRoster(false);}else if(a==='more-moves'){state.limit+=48;updateMoves(false);}else if(a==='more-passives'){state.limit+=24;updatePassives(false);}else if(a==='copy-link'){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(location.href).then(()=>toast('Enlace copiado')).catch(()=>toast('Copiá la dirección desde tu navegador'));else toast('Copiá la dirección desde tu navegador');}else if(a==='open-topic'){const section=document.getElementById('regla-'+target.dataset.id);if(section){section.open=true;section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}}});
 document.addEventListener('input',e=>{if(e.target===globalInput)searchGlobal();if(e.target.id==='roster-query')updateRoster();if(e.target.id==='move-query')updateMoves();if(e.target.id==='passive-query')updatePassives();});
 document.addEventListener('change',e=>{const id=e.target.id;if(id.startsWith('roster-'))updateRoster();else if(id.startsWith('move-'))updateMoves();else if(id==='passive-role')updatePassives();else if(id.startsWith('calc-'))updateCalculator();else if(id.startsWith('compare-'))updateCompare();else if(id==='qualidad-inverted')document.getElementById('character-affinities').innerHTML=affinityBlocks(byId.qualidad,e.target.checked);});
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape'){closeMenu();if(dialog.open)dialog.close();}});document.getElementById('drawer-scrim').addEventListener('click',closeMenu);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});window.addEventListener('hashchange',route);route();
 // Public read-only utilities support future catalog updates and verification.
 window.ColiseoWiki={data:D,markdown,route,search:C.searchCharacters,factor:(a,d)=>C.factor(D,a,d)};
})();
